// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CiRelation) predicate.CiRelation {
	return predicate.CiRelation(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CiRelation) predicate.CiRelation {
	return predicate.CiRelation(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CiRelation) predicate.CiRelation {
	return predicate.CiRelation(sql.NotPredicates(p))
}
